// Hyperbolic geometry in the Poincaré disk, in double precision on the CPU.
//
// The {p,q} tiling is generated by reflections in the sides of one triangle T
// with angles π/p (at the centre O), π/2 (at C, the midpoint of a polygon
// edge, on the positive real axis) and π/q (at B, a polygon corner, on the ray
// at angle π/p). Sides OC and OB are diameters; side BC is an arc of the
// circle |z − cx| = cr, which meets the unit circle at right angles.
//
// The fish live in the kite D = T ∪ (T reflected in OB) = O–C–B–C′, a
// fundamental domain for the rotations of the tiling. The geodesic L through
// C and C′ (perpendicular to OB at X) splits D into a 1/p slice of a ring
// centred on O and a 1/q slice of a ring centred on B.

const PI = Math.PI;

export function tilingParams(p, q) {
  const hf = PI / p;
  const seg = 2 * hf;
  const OC = Math.acosh(Math.cos(PI / q) / Math.sin(PI / p)); // centre to edge midpoint
  const xC = Math.tanh(OC / 2);
  const cx = (xC + 1 / xC) / 2; // mirror BC: centre and radius
  const cr = (1 / xC - xC) / 2;
  const OB = Math.acosh(1 / (Math.tan(PI / p) * Math.tan(PI / q))); // centre to corner
  const xB = Math.tanh(OB / 2);
  const ae = Math.acosh(Math.cos(PI / p) / Math.sin(PI / q)); // half an edge
  const ell = Math.asinh(Math.sinh(ae) * Math.sin(PI / q)); // half of C–C′ along L
  const dq = Math.atanh(Math.tanh(ae) * Math.cos(PI / q)); // corner B to X
  const dp = OB - dq; // centre O to X
  return {
    p, q, hf, seg, cx, cr, xB, ell, dp, dq,
    // packed for the shader: 4 × vec4
    packed: [
      p, q, seg, hf,
      cx, cr * cr, xB, ell,
      dp, dq, Math.tanh(dp / 2), Math.tanh(dq / 2),
      Math.tanh(dp), Math.tanh(dq), Math.sqrt(cr * cr), 0,
    ],
  };
}

// ---------------------------------------------------------------- complex
// A complex number is [re, im]. A map is { m: [a, b, c, d] (complex), flip }:
// f(z) = (a z̃ + b) / (c z̃ + d), where z̃ = conj(z) when flip is set.
const add = (a, b) => [a[0] + b[0], a[1] + b[1]];
const sub = (a, b) => [a[0] - b[0], a[1] - b[1]];
const mul = (a, b) => [a[0] * b[0] - a[1] * b[1], a[0] * b[1] + a[1] * b[0]];
const div = (a, b) => {
  const d = b[0] * b[0] + b[1] * b[1];
  return [(a[0] * b[0] + a[1] * b[1]) / d, (a[1] * b[0] - a[0] * b[1]) / d];
};
const conj = (a) => [a[0], -a[1]];
const cexp = (t) => [Math.cos(t), Math.sin(t)];
const abs = (a) => Math.hypot(a[0], a[1]);
const csqrt = (a) => {
  const r = Math.sqrt(abs(a));
  const t = Math.atan2(a[1], a[0]) / 2;
  return [r * Math.cos(t), r * Math.sin(t)];
};

export const identity = () => ({ m: [[1, 0], [0, 0], [0, 0], [1, 0]], flip: false });

export function apply(f, z) {
  const [a, b, c, d] = f.m;
  const zz = f.flip ? conj(z) : z;
  return div(add(mul(a, zz), b), add(mul(c, zz), d));
}

function matmul(A, B) {
  const [a, b, c, d] = A, [e, f, g, h] = B;
  return [add(mul(a, e), mul(b, g)), add(mul(a, f), mul(b, h)), add(mul(c, e), mul(d, g)), add(mul(c, f), mul(d, h))];
}

function normalize(f) {
  const [a, b, c, d] = f.m;
  const k = csqrt(sub(mul(a, d), mul(b, c)));
  f.m = f.m.map((x) => div(x, k));
  return f;
}

// left-compose a holomorphic matrix: g ∘ f
function leftHolo(G, f) { return { m: matmul(G, f.m), flip: f.flip }; }
// left-compose an anti-holomorphic map g(w) = G(conj w): g ∘ f
function leftAnti(G, f) { return { m: matmul(G, f.m.map(conj)), flip: !f.flip }; }
// right-compose a holomorphic matrix: f ∘ g (f must be holomorphic)
function rightHolo(f, G) { return { m: matmul(f.m, G), flip: f.flip }; }

// τ_c: the hyperbolic translation along the diameter through c taking 0 to c
const tau = (c) => [[1, 0], c, conj(c), [1, 0]];

// The pure hyperbolic translation along the geodesic through a and b, taking a to b.
export function translation(a, b) {
  const b1 = div(sub(b, a), sub([1, 0], mul(conj(a), b)));
  return matmul(matmul(tau(a), tau(b1)), tau([-a[0], -a[1]]));
}

// Translation along the geodesic through `a` in unit direction `dir` by hyperbolic distance s.
export function translationBy(a, dir, s) {
  const c = [dir[0] * Math.tanh(s / 2), dir[1] * Math.tanh(s / 2)];
  return matmul(matmul(tau(a), tau(c)), tau([-a[0], -a[1]]));
}

export function compose(f, G) { return normalize(rightHolo(f, G)); }

// hyperbolic distance between two points of the disk
export function dist(a, b) {
  const d = abs(div(sub(a, b), sub([1, 0], mul(conj(a), b))));
  return 2 * Math.atanh(Math.min(d, 1 - 1e-15));
}

// Re-express f so that f(0) lies in the kite D, by composing on the left with
// rotations of the tiling only. The picture is invariant under those, so the
// image does not change, but f stays well conditioned however far one drifts.
export function renormalize(f, P) {
  let g = { m: f.m, flip: f.flip };
  const R2 = P.cr * P.cr;
  for (let i = 0; i < 400; i++) {
    let w = apply(g, [0, 0]);
    let a = Math.atan2(w[1], w[0]);
    const k = Math.floor(a / P.seg);
    if (k !== 0) {
      g = leftHolo([cexp(-k * P.seg), [0, 0], [0, 0], [1, 0]], g);
      a -= k * P.seg;
    }
    if (a > P.hf) g = leftAnti([cexp(2 * P.hf), [0, 0], [0, 0], [1, 0]], g); // reflect in OB
    w = apply(g, [0, 0]);
    const dx = w[0] - P.cx, dy = w[1];
    if (dx * dx + dy * dy >= R2) break;
    // inversion in the circle (cx, cr): w ↦ cx + cr² / (conj(w) − cx)
    g = leftAnti([[P.cx, 0], [R2 - P.cx * P.cx, 0], [1, 0], [-P.cx, 0]], g);
  }
  if (g.flip) g = leftAnti([cexp(2 * P.hf), [0, 0], [0, 0], [1, 0]], g); // into D, orientation restored
  return normalize(g);
}

// Recentre helper: the translation that moves the view centre a fraction of the
// way back to the pattern point it currently shows, measured from the origin.
export function centreOf(f) { return apply(f, [0, 0]); }

export function flatten(f) {
  // a, b, c, d → two vec4 uniforms
  const [a, b, c, d] = f.m;
  return [[a[0], a[1], b[0], b[1]], [c[0], c[1], d[0], d[1]]];
}
